BOOK.add({
  subject: "math",
  id: "math-08",
  title: "चाल, समय एवं दूरी",
  notes: "\n<h3>1. मूल संबंध</h3>\n<div class=\"tip\"><b>दूरी = चाल × समय</b> &nbsp;|&nbsp; चाल = दूरी ÷ समय &nbsp;|&nbsp; समय = दूरी ÷ चाल<br>स्मृति त्रिभुज: ऊपर \"दू\" (दूरी), नीचे \"चा × स\" — जिसे ढूँढना हो उसे ढक दें।</div>\n<ul>\n<li>चाल स्थिर हो तो दूरी ∝ समय।</li>\n<li>समय स्थिर हो तो दूरी ∝ चाल।</li>\n<li>दूरी स्थिर हो तो चाल ∝ 1/समय — चालों का अनुपात 3 : 4 हो तो समयों का अनुपात 4 : 3।</li>\n</ul>\n\n<h3>2. इकाई रूपांतरण</h3>\n<table>\n<tr><th>रूपांतरण</th><th>गुणा करें</th><th>उदाहरण</th></tr>\n<tr><td>किमी/घंटा → मी/सेकंड</td><td>× 5/18</td><td>72 किमी/घं = 20 मी/से</td></tr>\n<tr><td>मी/सेकंड → किमी/घंटा</td><td>× 18/5</td><td>15 मी/से = 54 किमी/घं</td></tr>\n</table>\n<p>कारण: 1 किमी/घं = 1000 मी / 3600 से = 5/18 मी/से। अतः 1 मी/से = 3.6 किमी/घं।</p>\n<table>\n<tr><th>किमी/घं</th><td>18</td><td>36</td><td>54</td><td>72</td><td>90</td><td>108</td></tr>\n<tr><th>मी/से</th><td>5</td><td>10</td><td>15</td><td>20</td><td>25</td><td>30</td></tr>\n</table>\n\n<h3>3. औसत चाल</h3>\n<ul>\n<li><b>औसत चाल = कुल दूरी ÷ कुल समय</b> (चालों का साधारण औसत नहीं)।</li>\n<li>समान दूरी, दो चालें x, y ⇒ औसत चाल = <b>2xy/(x + y)</b>। 40 व 60 ⇒ 48 किमी/घं।</li>\n<li>समान दूरी, तीन चालें x, y, z ⇒ <b>3xyz/(xy + yz + zx)</b>। 10, 20, 60 ⇒ 18 किमी/घं।</li>\n<li>समान समय, चालें x, y ⇒ (x + y)/2।</li>\n<li>जाने की चाल x, औसत A चाहिए ⇒ लौटने की चाल y = Ax/(2x − A)। 40 पर जाकर औसत 48 के लिए y = 60।</li>\n</ul>\n\n<h3>4. सापेक्ष चाल</h3>\n<table>\n<tr><th>स्थिति</th><th>सापेक्ष चाल</th></tr>\n<tr><td>एक ही दिशा में</td><td>u − v (अंतर)</td></tr>\n<tr><td>विपरीत दिशा में (आमने-सामने या दूर जाते)</td><td>u + v (योग)</td></tr>\n</table>\n<ul>\n<li>दूरी D पर दो व्यक्ति आमने-सामने चलें ⇒ मिलने का समय = D/(u + v)। 100 किमी, 30 व 20 ⇒ 2 घंटे।</li>\n<li>चोर-सिपाही: अंतर d, एक ही दिशा ⇒ पकड़ने का समय = d/(u − v)।</li>\n<li>मिलन स्थल: तय दूरियाँ चालों के अनुपात में बँटती हैं — 450 किमी, 60 व 90 ⇒ A से 450 × 60/150 = 180 किमी।</li>\n<li>मिलने के बाद गंतव्य तक t<sub>1</sub> व t<sub>2</sub> समय लगे ⇒ चालों का अनुपात = <b>√t<sub>2</sub> : √t<sub>1</sub></b>। (9 और 16 घंटे ⇒ 4 : 3)</li>\n</ul>\n\n<h3>5. रेलगाड़ी (ट्रेन) के प्रश्न</h3>\n<table>\n<tr><th>ट्रेन किसे पार करती है</th><th>तय दूरी</th><th>चाल</th></tr>\n<tr><td>खंभा / खड़ा व्यक्ति / पेड़</td><td>ट्रेन की लंबाई L</td><td>ट्रेन की चाल</td></tr>\n<tr><td>प्लेटफ़ॉर्म / पुल / सुरंग (लंबाई P)</td><td>L + P</td><td>ट्रेन की चाल</td></tr>\n<tr><td>उसी दिशा में चलता व्यक्ति</td><td>L</td><td>u − v</td></tr>\n<tr><td>विपरीत दिशा में चलता व्यक्ति</td><td>L</td><td>u + v</td></tr>\n<tr><td>दूसरी ट्रेन (लंबाई L<sub>2</sub>), विपरीत दिशा</td><td>L<sub>1</sub> + L<sub>2</sub></td><td>u + v</td></tr>\n<tr><td>दूसरी ट्रेन, एक ही दिशा</td><td>L<sub>1</sub> + L<sub>2</sub></td><td>u − v</td></tr>\n</table>\n<p><b>उदाहरण 1:</b> 200 मी लंबी ट्रेन 72 किमी/घं (20 मी/से) से 300 मी प्लेटफ़ॉर्म को पार करती है: समय = 500 ÷ 20 = <b>25 सेकंड</b>।</p>\n<p><b>उदाहरण 2:</b> 100 मी व 150 मी लंबी ट्रेनें 50 व 40 किमी/घं से विपरीत दिशा में: सापेक्ष चाल 90 किमी/घं = 25 मी/से; समय = 250/25 = <b>10 सेकंड</b>। एक ही दिशा में: 10 किमी/घं = 25/9 मी/से; समय = 250 × 9/25 = <b>90 सेकंड</b>।</p>\n<p><b>उदाहरण 3:</b> ट्रेन खंभे को 15 सेकंड में और 250 मी प्लेटफ़ॉर्म को 25 सेकंड में पार करती है ⇒ 250 मी अतिरिक्त में 10 सेकंड ⇒ चाल 25 मी/से; लंबाई = 25 × 15 = <b>375 मी</b>।</p>\n\n<h3>6. नाव और धारा</h3>\n<p>नाव की स्थिर जल में चाल = u, धारा की चाल = v:</p>\n<ul>\n<li>धारा के <b>अनुकूल</b> (downstream) चाल D = u + v</li>\n<li>धारा के <b>प्रतिकूल</b> (upstream) चाल U = u − v</li>\n<li><b>u = (D + U)/2</b>, &nbsp; <b>v = (D − U)/2</b></li>\n<li>उदाहरण: D = 15, U = 9 ⇒ नाव 12, धारा 3 किमी/घं।</li>\n<li>प्रतिकूल जाने में समय, अनुकूल का k गुना ⇒ u : v = (k + 1) : (k − 1)। k = 2 ⇒ 3 : 1।</li>\n<li>दूरी d जाकर लौटने का कुल समय T ⇒ d = T(u² − v²)/(2u)।</li>\n</ul>\n\n<h3>7. देर/जल्दी पहुँचने के प्रश्न</h3>\n<ul>\n<li>चाल x पर t<sub>1</sub> देर, चाल y पर t<sub>2</sub> जल्दी ⇒ दूरी = <b>xy(t<sub>1</sub> + t<sub>2</sub>)/(y − x)</b> (t घंटों में)। 4 किमी/घं पर 10 मिनट देर, 5 पर 5 मिनट जल्दी ⇒ 4 × 5 × (15/60)/1 = 5 किमी।</li>\n<li>सामान्य चाल के a/b भाग से चलने पर t देर ⇒ सामान्य समय = t × a/(b − a)। 3/4 चाल पर 20 मिनट देर ⇒ 20 × 3/1 = 60 मिनट।</li>\n<li>चाल r% बढ़ाने पर समय की बचत = r/(100 + r) भाग। 10% तेज़ चलने पर 1 घंटा बचे ⇒ मूल समय = 11 घंटे।</li>\n</ul>\n\n<h3>8. दौड़ (Race) और वृत्ताकार पथ</h3>\n<ul>\n<li>\"A, B को x मी से हराता है\" ⇒ जब A रेखा पार करता है, B पीछे x मी।</li>\n<li>100 मी दौड़ में A, B को 10 मी से और B, C को 10 मी से ⇒ A, C को 100 − 90 × 0.9 = <b>19 मी</b> से हराता है।</li>\n<li>वृत्ताकार पथ (परिधि C): एक ही दिशा में पहली भेंट = C/(u − v); विपरीत दिशा में = C/(u + v)।</li>\n<li>पहिया: एक चक्कर में तय दूरी = परिधि = πd। 70 सेमी व्यास ⇒ 220 सेमी; 2.2 किमी में 1000 चक्कर।</li>\n</ul>\n\n<h3>9. ठहराव (Stoppage) के प्रश्न</h3>\n<p>बिना रुके चाल x, रुकते हुए चाल y ⇒ प्रति घंटा ठहराव = (x − y)/x × 60 मिनट। 54 व 45 ⇒ 9/54 × 60 = <b>10 मिनट</b>।</p>\n\n<h3>10. और हल सहित उदाहरण</h3>\n<p><b>उदाहरण 1:</b> A और B के बीच 330 किमी। ट्रेन A से 8 बजे 60 किमी/घं से, दूसरी B से 9 बजे 75 किमी/घं से चलती है। 9 बजे तक पहली 60 किमी चल चुकी; शेष 270 किमी को 135 किमी/घं से तय करने में 2 घंटे ⇒ मिलन <b>11 बजे</b>।</p>\n<p><b>उदाहरण 2:</b> 10 किमी/घं अधिक चाल से 300 किमी की यात्रा 1 घंटा कम में: 300/v − 300/(v + 10) = 1 ⇒ v(v + 10) = 3000 ⇒ v = <b>50 किमी/घं</b> (विकल्पों से जाँचना सबसे तेज़: 50 × 60 = 3000)।</p>\n<p><b>उदाहरण 3:</b> नाव धारा के अनुकूल 4 किमी जितने समय में जाती है, उतने में प्रतिकूल 3 किमी; 48 किमी जाकर लौटने में 14 घंटे ⇒ D = 8, U = 6 ⇒ धारा = <b>1 किमी/घं</b>, नाव = 7 किमी/घं।</p>\n<p><b>उदाहरण 4:</b> 1 किमी दौड़ में A 3 मिनट, B 3 मिनट 20 सेकंड ⇒ 180 सेकंड में B = 900 मी ⇒ A, B को <b>100 मी</b> से (या 20 सेकंड से) हराता है।</p>\n<p><b>उदाहरण 5:</b> 120 मी व 80 मी की ट्रेनें विपरीत दिशा में 10 सेकंड, एक दिशा में 40 सेकंड में पार ⇒ u + v = 20, u − v = 5 ⇒ तेज़ ट्रेन 12.5 मी/से = <b>45 किमी/घं</b>।</p>\n\n<h3>11. सूत्र-सार</h3>\n<table>\n<tr><th>स्थिति</th><th>सूत्र</th></tr>\n<tr><td>समान दूरी, दो चालें</td><td>2xy/(x + y)</td></tr>\n<tr><td>देर/जल्दी</td><td>दूरी = xy × (कुल समय-अंतर)/(y − x)</td></tr>\n<tr><td>मिलने के बाद t<sub>1</sub>, t<sub>2</sub></td><td>चाल अनुपात √t<sub>2</sub> : √t<sub>1</sub></td></tr>\n<tr><td>नाव</td><td>u = (D + U)/2, v = (D − U)/2</td></tr>\n<tr><td>ट्रेन-प्लेटफ़ॉर्म</td><td>समय = (L + P)/चाल</td></tr>\n<tr><td>वृत्ताकार पथ, एक दिशा</td><td>C/(u − v)</td></tr>\n</table>\n",
  extra: "\n<h3>शॉर्टकट व गहन ट्रिक्स</h3>\n<h4>1. 5/18 की तालिका मौखिक याद रखें</h4>\n<p>18 के गुणज वाली चालें सीधे बदलें: 18 → 5, 36 → 10, 54 → 15, 72 → 20, 90 → 25, 108 → 30, 126 → 35, 144 → 40। अन्य चालों के लिए: 45 किमी/घं = 12.5 मी/से, 60 = 16 2/3, 48 = 13 1/3, 66 = 18 1/3।</p>\n<h4>2. अनुपात विधि (समीकरण के बिना)</h4>\n<ul>\n<li>चाल 3/4 ⇒ समय 4/3 ⇒ अतिरिक्त 1/3 भाग = देरी।</li>\n<li>दो चालें 3 : 4, समय में अंतर 30 मिनट ⇒ समय 4 : 3, अंतर 1 भाग = 30 मिनट ⇒ धीमे को 2 घंटे।</li>\n<li>उसी समय में अधिक चाल से 20 किमी अधिक (30 बनाम 40) ⇒ 10t = 20 ⇒ t = 2 घंटे ⇒ वास्तविक दूरी 60 किमी।</li>\n</ul>\n<h4>3. एक साथ विपरीत छोर से चलना</h4>\n<p>A, X से Y तक 4 घंटे में, B, Y से X तक 6 घंटे में ⇒ मिलने का समय = (4 × 6)/(4 + 6) = 2.4 घंटे = 2 घंटे 24 मिनट।</p>\n<h4>4. ट्रेन — दो सूचनाओं से लंबाई और चाल</h4>\n<ul>\n<li>खंभा t<sub>1</sub> में, प्लेटफ़ॉर्म P को t<sub>2</sub> में ⇒ चाल = P/(t<sub>2</sub> − t<sub>1</sub>), लंबाई = चाल × t<sub>1</sub>।</li>\n<li>दो ट्रेनें विपरीत में t<sub>1</sub> में और एक दिशा में t<sub>2</sub> में पार करें ⇒ u + v = (L<sub>1</sub> + L<sub>2</sub>)/t<sub>1</sub>, u − v = (L<sub>1</sub> + L<sub>2</sub>)/t<sub>2</sub>।</li>\n<li>समान लंबाई की ट्रेनें: एक दिशा में 60 व 42 किमी/घं, 1 मिनट में पार ⇒ 5 मी/से × 60 = 300 मी = 2L ⇒ L = 150 मी।</li>\n</ul>\n<h4>5. नाव — समान समय में दो दूरियाँ</h4>\n<p>नाव 15 किमी/घं; अनुकूल 30 किमी और प्रतिकूल 20 किमी में समान समय ⇒ (15 + v) : (15 − v) = 30 : 20 = 3 : 2 ⇒ 2(15 + v) = 3(15 − v) ⇒ 30 + 2v = 45 − 3v ⇒ 5v = 15 ⇒ v = 3।</p>\n<h4>6. आम गलतियाँ</h4>\n<ul>\n<li>औसत चाल में (x + y)/2 लेना — केवल \"समान समय\" में सही है।</li>\n<li>ट्रेन-प्लेटफ़ॉर्म में केवल प्लेटफ़ॉर्म की लंबाई लेना — ट्रेन की लंबाई भी जोड़ें।</li>\n<li>किमी/घं और मी/से का मिश्रण — प्रश्न शुरू करने से पहले सभी इकाइयाँ एक जैसी कर लें।</li>\n<li>मिनट को घंटे में बदलना भूलना: 24 मिनट = 0.4 घंटा, 0.24 नहीं।</li>\n</ul>\n<h4>7. समकोण दिशाएँ</h4>\n<p>दो वाहन एक बिंदु से परस्पर लंबवत दिशाओं में 30 व 40 किमी/घं से ⇒ t घंटे बाद दूरी = √(30² + 40²) × t = 50t ⇒ 2 घंटे में 100 किमी (पाइथागोरस)।</p>\n",
  questions: [
    {"q":"72 किमी/घंटा = ? मी/सेकंड","o":["72 मी/से","20 मी/से","25 मी/से","36 मी/से"],"a":1,"e":"<b>हल:</b><br>चरण 1: किमी/घं से मी/से में बदलने के लिए 5/18 से गुणा करें (1 किमी = 1000 मी, 1 घं = 3600 से ⇒ 1000/3600 = 5/18)<br>चरण 2: 72 × 5/18 = 4 × 5 = 20<br>अतः उत्तर = <b>20 मी/से</b>"},
    {"q":"15 मी/सेकंड = ? किमी/घंटा","o":["45","60","54","50"],"a":2,"e":"<b>हल:</b><br>चरण 1: मी/से से किमी/घं में बदलने के लिए 18/5 से गुणा करें<br>चरण 2: 15 × 18/5 = 3 × 18 = 54<br>अतः उत्तर = <b>54 किमी/घं</b><br><b>ध्यान दें:</b> उल्टा 5/18 से गुणा करने की गलती न करें।"},
    {"q":"90 किमी/घंटा = ? मी/सेकंड","o":["30","15","20","25"],"a":3,"e":"<b>हल:</b><br>चरण 1: किमी/घं से मी/से में बदलने के लिए 5/18 से गुणा करें (1 किमी = 1000 मी, 1 घं = 3600 से ⇒ 1000/3600 = 5/18)<br>चरण 2: 90 × 5/18 = 5 × 5 = 25<br>अतः उत्तर = <b>25 मी/से</b>"},
    {"q":"एक कार 360 किमी की दूरी 4.5 घंटे में तय करती है। उसकी चाल क्या है?","o":["80 किमी/घं","75 किमी/घं","90 किमी/घं","72 किमी/घं"],"a":0,"e":"<b>हल:</b><br>चरण 1: सूत्र — चाल = दूरी ÷ समय<br>चरण 2: 360 ÷ 4.5 = 3600 ÷ 45 = 80<br>अतः उत्तर = <b>80 किमी/घं</b>"},
    {"q":"5 किमी/घं की चाल से 2 घंटे 24 मिनट में कितनी दूरी तय होगी?","o":["10 किमी","12 किमी","14 किमी","11 किमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: समय को घंटों में बदलें — 24 मिनट = 24/60 = 0.4 घंटा ⇒ 2.4 घंटे<br>चरण 2: दूरी = चाल × समय = 5 × 2.4 = 12<br>अतः उत्तर = <b>12 किमी</b><br><b>ध्यान दें:</b> 2 घंटे 24 मिनट को 2.24 घंटे लिखना आम गलती है।"},
    {"q":"एक व्यक्ति कुछ दूरी 30 किमी/घं से और उतनी ही दूरी 20 किमी/घं से तय करता है। औसत चाल क्या है?","o":["25 किमी/घं","26 किमी/घं","24 किमी/घं","22 किमी/घं"],"a":2,"e":"<b>हल:</b><br>चरण 1: समान दूरी दो चालों से ⇒ औसत चाल = 2xy/(x + y) (हरात्मक माध्य)<br>चरण 2: 2 × 30 × 20/(30 + 20) = 1200/50 = 24<br>अतः उत्तर = <b>24 किमी/घं</b><br><b>जाँच:</b> दूरी 60 मानें — समय 2 + 3 = 5 घंटे, कुल 120 किमी ⇒ 120/5 = 24<br><b>ध्यान दें:</b> 25 (साधारण औसत) गलत है।"},
    {"q":"एक व्यक्ति तीन समान दूरियाँ क्रमशः 10, 20 और 60 किमी/घं से तय करता है। उसकी औसत चाल क्या है?","o":["30 किमी/घं","20 किमी/घं","15 किमी/घं","18 किमी/घं"],"a":3,"e":"<b>हल:</b><br>चरण 1: तीन समान दूरियाँ ⇒ औसत चाल = 3xyz/(xy + yz + zx)<br>चरण 2: xyz = 10 × 20 × 60 = 12000; xy + yz + zx = 200 + 1200 + 600 = 2000<br>चरण 3: 3 × 12000/2000 = 18<br>अतः उत्तर = <b>18 किमी/घं</b><br><b>जाँच:</b> हर दूरी 60 किमी — समय 6 + 3 + 1 = 10 घंटे; 180/10 = 18<br><b>ध्यान दें:</b> 30 (साधारण औसत) गलत है।"},
    {"q":"एक बस 2 घंटे 40 किमी/घं से और 3 घंटे 50 किमी/घं से चलती है। औसत चाल क्या है?","o":["46 किमी/घं","45 किमी/घं","44 किमी/घं","48 किमी/घं"],"a":0,"e":"<b>हल:</b><br>चरण 1: औसत चाल = कुल दूरी ÷ कुल समय<br>चरण 2: दूरी = 2 × 40 + 3 × 50 = 80 + 150 = 230 किमी; समय = 5 घंटे<br>चरण 3: 230/5 = 46<br>अतः उत्तर = <b>46 किमी/घं</b><br><b>ध्यान दें:</b> 45 (चालों का साधारण औसत) गलत — समय अलग-अलग है।"},
    {"q":"150 मी लंबी ट्रेन एक खंभे को 15 सेकंड में पार करती है। ट्रेन की चाल क्या है?","o":["30 किमी/घं","36 किमी/घं","40 किमी/घं","54 किमी/घं"],"a":1,"e":"<b>हल:</b><br>चरण 1: खंभे को पार करने में ट्रेन अपनी लंबाई जितनी दूरी तय करती है<br>चरण 2: चाल = 150/15 = 10 मी/से<br>चरण 3: किमी/घं में = 10 × 18/5 = 36<br>अतः उत्तर = <b>36 किमी/घं</b>"},
    {"q":"200 मी लंबी ट्रेन 72 किमी/घं की चाल से 300 मी लंबे प्लेटफ़ॉर्म को कितने समय में पार करेगी?","o":["20 सेकंड","30 सेकंड","25 सेकंड","35 सेकंड"],"a":2,"e":"<b>हल:</b><br>चरण 1: प्लेटफ़ॉर्म पार करने में दूरी = ट्रेन + प्लेटफ़ॉर्म = 200 + 300 = 500 मी<br>चरण 2: चाल = 72 × 5/18 = 20 मी/से<br>चरण 3: समय = 500/20 = 25 सेकंड<br>अतः उत्तर = <b>25 सेकंड</b><br><b>ध्यान दें:</b> केवल प्लेटफ़ॉर्म (300) लेने पर 15 सेकंड आता है — गलत।"},
    {"q":"120 मी लंबी ट्रेन 54 किमी/घं से चल रही है। वह उसी दिशा में 6 किमी/घं से चल रहे व्यक्ति को कितने समय में पार करेगी?","o":["8 सेकंड","10 सेकंड","12 सेकंड","9 सेकंड"],"a":3,"e":"<b>हल:</b><br>चरण 1: एक ही दिशा ⇒ सापेक्ष चाल = 54 − 6 = 48 किमी/घं<br>चरण 2: 48 × 5/18 = 40/3 मी/से<br>चरण 3: व्यक्ति बिंदु-वस्तु है ⇒ दूरी = ट्रेन की लंबाई 120 मी<br>चरण 4: समय = 120 ÷ 40/3 = 120 × 3/40 = 9 सेकंड<br>अतः उत्तर = <b>9 सेकंड</b><br><b>ध्यान दें:</b> चालें जोड़ने (60 किमी/घं) पर 7.2 सेकंड आता है — वह विपरीत दिशा का नियम है।"},
    {"q":"100 मी और 150 मी लंबी दो ट्रेनें 50 और 40 किमी/घं की चाल से विपरीत दिशाओं में चल रही हैं। वे एक-दूसरे को कितने समय में पार करेंगी?","o":["10 सेकंड","25 सेकंड","15 सेकंड","12 सेकंड"],"a":0,"e":"<b>हल:</b><br>चरण 1: विपरीत दिशा ⇒ सापेक्ष चाल = 50 + 40 = 90 किमी/घं = 90 × 5/18 = 25 मी/से<br>चरण 2: कुल दूरी = दोनों लंबाइयों का योग = 100 + 150 = 250 मी<br>चरण 3: समय = 250/25 = 10 सेकंड<br>अतः उत्तर = <b>10 सेकंड</b>"},
    {"q":"100 मी और 150 मी लंबी दो ट्रेनें 50 और 40 किमी/घं से एक ही दिशा में चल रही हैं। तेज़ ट्रेन धीमी को कितने समय में पार करेगी?","o":["60 सेकंड","90 सेकंड","45 सेकंड","100 सेकंड"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक ही दिशा ⇒ सापेक्ष चाल = 50 − 40 = 10 किमी/घं = 10 × 5/18 = 25/9 मी/से<br>चरण 2: दूरी = 100 + 150 = 250 मी<br>चरण 3: समय = 250 ÷ 25/9 = 250 × 9/25 = 90 सेकंड<br>अतः उत्तर = <b>90 सेकंड</b>"},
    {"q":"स्थिर जल में नाव की चाल 10 किमी/घं और धारा की चाल 2 किमी/घं है। धारा के अनुकूल 24 किमी जाने में कितना समय लगेगा?","o":["3 घंटे","2.4 घंटे","2 घंटे","2.5 घंटे"],"a":2,"e":"<b>हल:</b><br>चरण 1: धारा के अनुकूल चाल = नाव + धारा = 10 + 2 = 12 किमी/घं<br>चरण 2: समय = 24/12 = 2 घंटे<br>अतः उत्तर = <b>2 घंटे</b><br><b>ध्यान दें:</b> 3 घंटे प्रतिकूल चाल (8) लेने से आता है।"},
    {"q":"एक नाव की धारा के अनुकूल चाल 15 किमी/घं और प्रतिकूल चाल 9 किमी/घं है। स्थिर जल में नाव की चाल क्या है?","o":["10 किमी/घं","3 किमी/घं","6 किमी/घं","12 किमी/घं"],"a":3,"e":"<b>हल:</b><br>चरण 1: अनुकूल D = B + S, प्रतिकूल U = B − S<br>चरण 2: नाव की चाल B = (D + U)/2 = (15 + 9)/2 = 12<br>अतः उत्तर = <b>12 किमी/घं</b><br><b>ध्यान दें:</b> 3 किमी/घं धारा की चाल है।"},
    {"q":"एक नाव की धारा के अनुकूल चाल 18 किमी/घं और प्रतिकूल चाल 10 किमी/घं है। धारा की चाल क्या है?","o":["3 किमी/घं","4 किमी/घं","8 किमी/घं","14 किमी/घं"],"a":1,"e":"<b>हल:</b><br>चरण 1: धारा की चाल S = (D − U)/2<br>चरण 2: (18 − 10)/2 = 4<br>अतः उत्तर = <b>4 किमी/घं</b><br><b>ध्यान दें:</b> 8 (2 से भाग न देना) और 14 (नाव की चाल) गलत हैं।"},
    {"q":"एक व्यक्ति 48 किमी धारा के अनुकूल जाकर वापस 14 घंटे में लौटता है। वह जितने समय में अनुकूल 4 किमी जाता है, उतने में प्रतिकूल 3 किमी। धारा की चाल क्या है?","o":["1.5 किमी/घं","2 किमी/घं","1 किमी/घं","2.5 किमी/घं"],"a":2,"e":"<b>हल:</b><br>चरण 1: समान समय में दूरी ∝ चाल ⇒ D : U = 4 : 3; माना D = 4x, U = 3x<br>चरण 2: कुल समय = 48/4x + 48/3x = 12/x + 16/x = 28/x<br>चरण 3: 28/x = 14 ⇒ x = 2 ⇒ D = 8, U = 6<br>चरण 4: धारा की चाल = (8 − 6)/2 = 1<br>अतः उत्तर = <b>1 किमी/घं</b><br><b>ध्यान दें:</b> 2 किमी/घं = D − U है; 2 से भाग देना न भूलें।"},
    {"q":"दो वाहनों की चालों का अनुपात 3 : 4 है। समान दूरी तय करने में लगे समयों का अनुपात क्या होगा?","o":["3 : 4","4 : 3","9 : 16","16 : 9"],"a":1,"e":"<b>हल:</b><br>चरण 1: दूरी समान ⇒ समय ∝ 1/चाल<br>चरण 2: समय का अनुपात = 1/3 : 1/4 = 4 : 3<br>अतः उत्तर = <b>4 : 3</b>"},
    {"q":"एक व्यक्ति अपनी सामान्य चाल की 3/4 चाल से चलकर कार्यालय 20 मिनट देर से पहुँचता है। सामान्य चाल से उसे कितना समय लगता है?","o":["40 मिनट","80 मिनट","60 मिनट","45 मिनट"],"a":2,"e":"<b>हल:</b><br>चरण 1: चाल 3/4 हुई ⇒ समय 4/3 गुना<br>चरण 2: अतिरिक्त समय = 4T/3 − T = T/3<br>चरण 3: T/3 = 20 मिनट ⇒ T = 60 मिनट<br>अतः उत्तर = <b>60 मिनट</b><br><b>ध्यान दें:</b> 80 मिनट धीमी चाल से लगा समय है।"},
    {"q":"एक छात्र 4 किमी/घं से चलकर विद्यालय 10 मिनट देर से और 5 किमी/घं से चलकर 5 मिनट पहले पहुँचता है। विद्यालय की दूरी कितनी है?","o":["4 किमी","6 किमी","4.5 किमी","5 किमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: दोनों समयों का अंतर = 10 मिनट देर + 5 मिनट पहले = 15 मिनट = 1/4 घंटा<br>चरण 2: d/4 − d/5 = 1/4 ⇒ (5d − 4d)/20 = 1/4 ⇒ d/20 = 1/4<br>चरण 3: d = 5<br>अतः उत्तर = <b>5 किमी</b><br><b>शॉर्टकट:</b> d = (गुणनफल/अंतर) × समयांतर = (4 × 5/1) × 1/4 = 5<br><b>ध्यान दें:</b> समयांतर 5 मिनट (10 − 5) लेना गलत है — एक देर है, एक पहले।"},
    {"q":"100 किमी दूर दो स्थानों से दो व्यक्ति एक साथ 30 और 20 किमी/घं से एक-दूसरे की ओर चलते हैं। वे कितने समय बाद मिलेंगे?","o":["2 घंटे","3 घंटे","2.5 घंटे","4 घंटे"],"a":0,"e":"<b>हल:</b><br>चरण 1: आमने-सामने ⇒ सापेक्ष चाल = 30 + 20 = 50 किमी/घं<br>चरण 2: समय = 100/50 = 2 घंटे<br>अतः उत्तर = <b>2 घंटे</b>"},
    {"q":"एक चोर सिपाही से 100 मी आगे है। चोर 8 किमी/घं और सिपाही 10 किमी/घं से दौड़ते हैं। सिपाही चोर को कितने समय में पकड़ेगा?","o":["5 मिनट","3 मिनट","6 मिनट","2 मिनट"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक ही दिशा ⇒ सापेक्ष चाल = 10 − 8 = 2 किमी/घं<br>चरण 2: दूरी = 100 मी = 0.1 किमी<br>चरण 3: समय = 0.1/2 = 0.05 घंटा = 0.05 × 60 = 3 मिनट<br>अतः उत्तर = <b>3 मिनट</b>"},
    {"q":"एक ट्रेन एक खंभे को 15 सेकंड में और 250 मी लंबे प्लेटफ़ॉर्म को 25 सेकंड में पार करती है। ट्रेन की लंबाई कितनी है?","o":["250 मी","350 मी","375 मी","400 मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: खंभा: L = v × 15; प्लेटफ़ॉर्म: L + 250 = v × 25<br>चरण 2: घटाएँ ⇒ 250 = v × 10 ⇒ v = 25 मी/से<br>चरण 3: L = 25 × 15 = 375 मी<br>अतः उत्तर = <b>375 मी</b><br><b>ध्यान दें:</b> अतिरिक्त 10 सेकंड केवल प्लेटफ़ॉर्म की लंबाई के लिए हैं।"},
    {"q":"110 मी लंबी ट्रेन 60 किमी/घं से चल रही है। विपरीत दिशा में 6 किमी/घं से दौड़ते व्यक्ति को वह कितने समय में पार करेगी?","o":["5 सेकंड","7 सेकंड","8 सेकंड","6 सेकंड"],"a":3,"e":"<b>हल:</b><br>चरण 1: विपरीत दिशा ⇒ सापेक्ष चाल = 60 + 6 = 66 किमी/घं<br>चरण 2: 66 × 5/18 = 55/3 मी/से<br>चरण 3: समय = 110 ÷ 55/3 = 110 × 3/55 = 6 सेकंड<br>अतः उत्तर = <b>6 सेकंड</b>"},
    {"q":"एक कार 60 किमी/घं से कोई दूरी 8 घंटे में तय करती है। वही दूरी 6 घंटे में तय करने के लिए चाल कितनी होनी चाहिए?","o":["80 किमी/घं","75 किमी/घं","90 किमी/घं","70 किमी/घं"],"a":0,"e":"<b>हल:</b><br>चरण 1: दूरी = 60 × 8 = 480 किमी<br>चरण 2: नई चाल = 480/6 = 80<br>अतः उत्तर = <b>80 किमी/घं</b><br><b>शॉर्टकट:</b> चाल ∝ 1/समय ⇒ 60 × 8/6 = 80"},
    {"q":"70 सेमी व्यास वाला पहिया 2.2 किमी दूरी तय करने में कितने चक्कर लगाएगा? (π = 22/7)","o":["500","1000","1100","2000"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक चक्कर में दूरी = परिधि = πd = 22/7 × 70 = 220 सेमी<br>चरण 2: कुल दूरी = 2.2 किमी = 2,20,000 सेमी<br>चरण 3: चक्कर = 2,20,000/220 = 1000<br>अतः उत्तर = <b>1000</b><br><b>ध्यान दें:</b> परिधि में त्रिज्या (35) के स्थान पर व्यास लेने के सूत्र पर ध्यान दें — 2πr = πd।"},
    {"q":"एक व्यक्ति 30 किमी 15 किमी/घं से और अगले 30 किमी 10 किमी/घं से तय करता है। उसकी औसत चाल क्या है?","o":["12.5 किमी/घं","13 किमी/घं","12 किमी/घं","11 किमी/घं"],"a":2,"e":"<b>हल:</b><br>चरण 1: पहले भाग का समय = 30/15 = 2 घंटे; दूसरे का = 30/10 = 3 घंटे<br>चरण 2: कुल दूरी = 60 किमी; कुल समय = 5 घंटे<br>चरण 3: औसत चाल = 60/5 = 12<br>अतः उत्तर = <b>12 किमी/घं</b><br><b>शॉर्टकट:</b> समान दूरी ⇒ 2 × 15 × 10/25 = 12<br><b>ध्यान दें:</b> 12.5 साधारण औसत है — गलत।"},
    {"q":"ठहराव को छोड़कर एक बस की चाल 54 किमी/घं और ठहराव सहित 45 किमी/घं है। बस प्रति घंटा कितने मिनट रुकती है?","o":["9 मिनट","12 मिनट","15 मिनट","10 मिनट"],"a":3,"e":"<b>हल:</b><br>चरण 1: ठहराव के कारण प्रति घंटा कम दूरी = 54 − 45 = 9 किमी<br>चरण 2: 9 किमी तय करने में 54 किमी/घं से लगने वाला समय = 9/54 घंटा<br>चरण 3: 9/54 × 60 = 10 मिनट<br>अतः उत्तर = <b>10 मिनट</b><br><b>ध्यान दें:</b> 12 मिनट गलत आधार (45) से आता है।"},
    {"q":"18 किमी/घं = ? मी/से","o":["5","6","4","10"],"a":0,"e":"<b>हल:</b><br>चरण 1: किमी/घं से मी/से में बदलने के लिए 5/18 से गुणा करें (1 किमी = 1000 मी, 1 घं = 3600 से ⇒ 1000/3600 = 5/18)<br>चरण 2: 18 × 5/18 = 5<br>अतः उत्तर = <b>5 मी/से</b>"},
    {"q":"1 मी/से = ? किमी/घं","o":["5/18","3.6","1.8","0.36"],"a":1,"e":"<b>हल:</b><br>चरण 1: मी/से से किमी/घं ⇒ × 18/5<br>चरण 2: 1 × 18/5 = 3.6<br>अतः उत्तर = <b>3.6 किमी/घं</b><br><b>ध्यान दें:</b> 5/18 उल्टा रूपांतरण है।"},
    {"q":"एक साइकिल सवार 1 किमी की दूरी 1 मिनट 40 सेकंड में तय करता है। उसकी चाल किमी/घं में क्या है?","o":["30","40","36","60"],"a":2,"e":"<b>हल:</b><br>चरण 1: समय = 1 मिनट 40 सेकंड = 100 सेकंड; दूरी = 1000 मी<br>चरण 2: चाल = 1000/100 = 10 मी/से<br>चरण 3: 10 × 18/5 = 36 किमी/घं<br>अतः उत्तर = <b>36</b>"},
    {"q":"A और B के बीच 330 किमी की दूरी है। एक ट्रेन A से सुबह 8 बजे 60 किमी/घं से B की ओर और दूसरी B से सुबह 9 बजे 75 किमी/घं से A की ओर चलती है। वे कब मिलेंगी?","o":["10 AM","10:30 AM","12 PM","11 AM"],"a":3,"e":"<b>हल:</b><br>चरण 1: 8 से 9 बजे तक पहली ट्रेन = 60 किमी चली ⇒ शेष दूरी = 330 − 60 = 270 किमी<br>चरण 2: 9 बजे से दोनों आमने-सामने ⇒ सापेक्ष चाल = 60 + 75 = 135 किमी/घं<br>चरण 3: समय = 270/135 = 2 घंटे ⇒ 9 + 2 = 11 बजे<br>अतः उत्तर = <b>11 AM</b><br><b>ध्यान दें:</b> 330/135 ≈ 2.44 घंटे लेना गलत — दूसरी ट्रेन 1 घंटा देर से चली।"},
    {"q":"दो ट्रेनें P और Q से एक साथ एक-दूसरे की ओर चलती हैं। मिलने के बाद उन्हें गंतव्य तक पहुँचने में क्रमशः 9 घंटे और 16 घंटे लगते हैं। उनकी चालों का अनुपात क्या है?","o":["4 : 3","3 : 4","16 : 9","9 : 16"],"a":0,"e":"<b>हल:</b><br>चरण 1: नियम — मिलने के बाद लगे समय t₁, t₂ हों तो S₁ : S₂ = √t₂ : √t₁<br>चरण 2: S_P : S_Q = √16 : √9 = 4 : 3<br>अतः उत्तर = <b>4 : 3</b><br><b>ध्यान दें:</b> 3 : 4 (√9 : √16) उल्टा क्रम है — अधिक समय लेने वाली ट्रेन धीमी है।"},
    {"q":"यदि कोई कार अपनी चाल 10% बढ़ा दे, तो यात्रा में 1 घंटा बचता है। सामान्य चाल से यात्रा में कितना समय लगता है?","o":["10 घंटे","11 घंटे","12 घंटे","9 घंटे"],"a":1,"e":"<b>हल:</b><br>चरण 1: चाल 10% बढ़ी ⇒ चाल 11/10 गुनी ⇒ समय 10/11 गुना<br>चरण 2: बचत = T − 10T/11 = T/11<br>चरण 3: T/11 = 1 घंटा ⇒ T = 11 घंटे<br>अतः उत्तर = <b>11 घंटे</b><br><b>ध्यान दें:</b> 10 घंटे नया (बढ़ी चाल वाला) समय है।"},
    {"q":"स्थिर जल में 6 किमी/घं से नाव चलाने वाला व्यक्ति 2 किमी/घं की धारा में 16 किमी जाकर लौटता है। कुल कितना समय लगेगा?","o":["5 घंटे","4 घंटे","6 घंटे","8 घंटे"],"a":2,"e":"<b>हल:</b><br>चरण 1: अनुकूल चाल = 6 + 2 = 8 किमी/घं; प्रतिकूल = 6 − 2 = 4 किमी/घं<br>चरण 2: जाने का समय = 16/8 = 2 घंटे; लौटने का = 16/4 = 4 घंटे<br>चरण 3: कुल = 2 + 4 = 6 घंटे<br>अतः उत्तर = <b>6 घंटे</b><br><b>ध्यान दें:</b> धारा की उपेक्षा कर 32/6 ≈ 5.33 घंटे लेना गलत है।"},
    {"q":"एक व्यक्ति धारा के अनुकूल 12 किमी 2 घंटे में और प्रतिकूल 8 किमी 2 घंटे में जाता है। स्थिर जल में उसकी चाल क्या है?","o":["4 किमी/घं","6 किमी/घं","4.5 किमी/घं","5 किमी/घं"],"a":3,"e":"<b>हल:</b><br>चरण 1: अनुकूल चाल D = 12/2 = 6 किमी/घं; प्रतिकूल U = 8/2 = 4 किमी/घं<br>चरण 2: स्थिर जल में चाल = (D + U)/2 = (6 + 4)/2 = 5<br>अतः उत्तर = <b>5 किमी/घं</b>"},
    {"q":"100 मी की दौड़ में A, B को 10 मी से और B, C को 10 मी से हराता है। A, C को कितने मीटर से हराएगा?","o":["19 मी","20 मी","18 मी","21 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: जब A 100 मी दौड़ता है, B 90 मी दौड़ता है<br>चरण 2: जब B 100 मी दौड़ता है, C 90 मी ⇒ B 90 मी पर C = 90 × 90/100 = 81 मी<br>चरण 3: अतः A के 100 मी पर C = 81 मी ⇒ अंतर = 19 मी<br>अतः उत्तर = <b>19 मी</b><br><b>ध्यान दें:</b> 20 मी (10 + 10) सीधा जोड़ना गलत है।"},
    {"q":"A 1 किमी 3 मिनट में और B 3 मिनट 20 सेकंड में दौड़ता है। 1 किमी की दौड़ में A, B को कितनी दूरी से हराएगा?","o":["80 मी","100 मी","120 मी","90 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: A का समय = 3 मिनट = 180 सेकंड; B का = 3 मिनट 20 सेकंड = 200 सेकंड<br>चरण 2: B की चाल = 1000/200 = 5 मी/से<br>चरण 3: A के समाप्त होने (180 से) तक B = 5 × 180 = 900 मी<br>चरण 4: A, B को 1000 − 900 = 100 मी से हराता है<br>अतः उत्तर = <b>100 मी</b>"},
    {"q":"600 मी परिधि वाले वृत्ताकार पथ पर A और B एक ही बिंदु से एक ही दिशा में 4 मी/से और 6 मी/से से दौड़ते हैं। वे पहली बार कब मिलेंगे?","o":["60 सेकंड","120 सेकंड","300 सेकंड","100 सेकंड"],"a":2,"e":"<b>हल:</b><br>चरण 1: एक ही दिशा ⇒ सापेक्ष चाल = 6 − 4 = 2 मी/से<br>चरण 2: पहली बार मिलने के लिए तेज़ को धीमे से एक पूरा चक्कर (600 मी) अधिक चलना है<br>चरण 3: समय = 600/2 = 300 सेकंड<br>अतः उत्तर = <b>300 सेकंड</b><br><b>ध्यान दें:</b> 60 सेकंड विपरीत दिशा का उत्तर है।"},
    {"q":"600 मी परिधि वाले वृत्ताकार पथ पर A और B एक ही बिंदु से विपरीत दिशाओं में 4 मी/से और 6 मी/से से दौड़ते हैं। वे पहली बार कब मिलेंगे?","o":["300 सेकंड","100 सेकंड","120 सेकंड","60 सेकंड"],"a":3,"e":"<b>हल:</b><br>चरण 1: विपरीत दिशा ⇒ सापेक्ष चाल = 4 + 6 = 10 मी/से<br>चरण 2: मिलकर एक पूरा चक्कर (600 मी) तय करने पर मिलेंगे<br>चरण 3: समय = 600/10 = 60 सेकंड<br>अतः उत्तर = <b>60 सेकंड</b>"},
    {"q":"एक ट्रेन 800 मी लंबे पुल को 100 सेकंड में और एक लैंप-पोस्ट को 20 सेकंड में पार करती है। ट्रेन की चाल क्या है?","o":["36 किमी/घं","40 किमी/घं","45 किमी/घं","54 किमी/घं"],"a":0,"e":"<b>हल:</b><br>चरण 1: लैंप-पोस्ट: L = v × 20; पुल: L + 800 = v × 100<br>चरण 2: घटाएँ ⇒ 800 = v × 80 ⇒ v = 10 मी/से<br>चरण 3: 10 × 18/5 = 36 किमी/घं<br>अतः उत्तर = <b>36 किमी/घं</b><br><b>ध्यान दें:</b> 800/100 = 8 मी/से लेना गलत — 100 सेकंड में ट्रेन की लंबाई भी शामिल है।"},
    {"q":"48 किमी/घं की चाल से 1 घंटा 15 मिनट में कितनी दूरी तय होगी?","o":["50 किमी","60 किमी","64 किमी","56 किमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: समय = 1 घंटा 15 मिनट = 1 + 15/60 = 1.25 घंटे<br>चरण 2: दूरी = 48 × 1.25 = 60 किमी<br>अतः उत्तर = <b>60 किमी</b><br><b>ध्यान दें:</b> 1.15 घंटे लेने पर 55.2 आता है — गलत।"},
    {"q":"A और B की चालों का अनुपात 3 : 4 है। एक निश्चित दूरी तय करने में A को B से 30 मिनट अधिक लगते हैं। A को कितना समय लगता है?","o":["1.5 घंटे","2.5 घंटे","2 घंटे","1 घंटा"],"a":2,"e":"<b>हल:</b><br>चरण 1: दूरी समान ⇒ समय का अनुपात = चाल का उल्टा = 4 : 3 (A : B)<br>चरण 2: अंतर = 4 − 3 = 1 भाग = 30 मिनट<br>चरण 3: A = 4 भाग = 120 मिनट = 2 घंटे<br>अतः उत्तर = <b>2 घंटे</b><br><b>ध्यान दें:</b> 1.5 घंटे B का समय है।"},
    {"q":"दो कारें एक ही बिंदु से परस्पर लंबवत दिशाओं में 30 और 40 किमी/घं से चलती हैं। 2 घंटे बाद उनके बीच दूरी कितनी होगी?","o":["140 किमी","70 किमी","120 किमी","100 किमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: 2 घंटे में दूरियाँ — 30 × 2 = 60 किमी, 40 × 2 = 80 किमी (परस्पर लंबवत)<br>चरण 2: पाइथागोरस प्रमेय ⇒ दूरी = √(60² + 80²) = √(3600 + 6400) = √10000<br>चरण 3: = 100 किमी<br>अतः उत्तर = <b>100 किमी</b><br><b>ध्यान दें:</b> 140 (60 + 80) सीधा जोड़ना गलत है — वह विपरीत दिशा में होता।"},
    {"q":"300 मी लंबी ट्रेन 90 किमी/घं से एक सुरंग को 1 मिनट में पार करती है। सुरंग की लंबाई कितनी है?","o":["1200 मी","1500 मी","900 मी","1000 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: चाल = 90 × 5/18 = 25 मी/से; समय = 60 सेकंड<br>चरण 2: तय दूरी = 25 × 60 = 1500 मी = ट्रेन + सुरंग<br>चरण 3: सुरंग = 1500 − 300 = 1200 मी<br>अतः उत्तर = <b>1200 मी</b><br><b>ध्यान दें:</b> 1500 मी में ट्रेन की लंबाई भी शामिल है।"},
    {"q":"समान लंबाई की दो ट्रेनें एक ही दिशा में 60 और 42 किमी/घं से चल रही हैं। तेज़ ट्रेन धीमी को 1 मिनट में पार करती है। प्रत्येक ट्रेन की लंबाई कितनी है?","o":["300 मी","150 मी","200 मी","250 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक ही दिशा ⇒ सापेक्ष चाल = 60 − 42 = 18 किमी/घं = 18 × 5/18 = 5 मी/से<br>चरण 2: 1 मिनट (60 सेकंड) में दूरी = 5 × 60 = 300 मी = दोनों लंबाइयों का योग = 2L<br>चरण 3: L = 150 मी<br>अतः उत्तर = <b>150 मी</b><br><b>ध्यान दें:</b> 300 मी दोनों ट्रेनों की कुल लंबाई है।"},
    {"q":"एक नाव को धारा के प्रतिकूल जाने में अनुकूल की तुलना में दोगुना समय लगता है। नाव की चाल और धारा की चाल का अनुपात क्या है?","o":["2 : 1","1 : 3","3 : 1","3 : 2"],"a":2,"e":"<b>हल:</b><br>चरण 1: दूरी समान, प्रतिकूल समय = 2 × अनुकूल समय ⇒ अनुकूल चाल = 2 × प्रतिकूल चाल<br>चरण 2: माना नाव = u, धारा = v ⇒ u + v = 2(u − v)<br>चरण 3: u + v = 2u − 2v ⇒ u = 3v<br>चरण 4: u : v = 3 : 1<br>अतः उत्तर = <b>3 : 1</b><br><b>शॉर्टकट:</b> D : U = 2 : 1 ⇒ नाव : धारा = (2 + 1) : (2 − 1) = 3 : 1"},
    {"q":"स्थिर जल में नाव की चाल 15 किमी/घं है। वह धारा के अनुकूल 30 किमी और प्रतिकूल 20 किमी समान समय में जाती है। धारा की चाल क्या है?","o":["2 किमी/घं","4 किमी/घं","5 किमी/घं","3 किमी/घं"],"a":3,"e":"<b>हल:</b><br>चरण 1: समय समान ⇒ 30/(15 + v) = 20/(15 − v)<br>चरण 2: 30(15 − v) = 20(15 + v) ⇒ 450 − 30v = 300 + 20v<br>चरण 3: 150 = 50v ⇒ v = 3<br>अतः उत्तर = <b>3 किमी/घं</b><br><b>जाँच:</b> 30/18 = 20/12 = 5/3 घंटे ✓"},
    {"q":"दो स्टेशनों के बीच 240 किमी की दूरी है। एक ट्रेन 60 किमी/घं से जाती है और 40 किमी/घं से लौटती है। आने-जाने में कुल कितना समय लगता है?","o":["10 घंटे","8 घंटे","12 घंटे","9 घंटे"],"a":0,"e":"<b>हल:</b><br>चरण 1: जाने का समय = 240/60 = 4 घंटे<br>चरण 2: लौटने का समय = 240/40 = 6 घंटे<br>चरण 3: कुल = 4 + 6 = 10 घंटे<br>अतः उत्तर = <b>10 घंटे</b>"},
    {"q":"18 किमी/घं से चलने वाला साइकिल सवार 25 मिनट में कितनी दूरी तय करेगा?","o":["7 किमी","7.5 किमी","8 किमी","6.5 किमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: समय = 25 मिनट = 25/60 घंटा<br>चरण 2: दूरी = 18 × 25/60 = 450/60 = 7.5 किमी<br>अतः उत्तर = <b>7.5 किमी</b><br><b>शॉर्टकट:</b> 18 किमी/घं = 5 मी/से; 5 × 1500 सेकंड = 7500 मी"},
    {"q":"एक ट्रेन अपनी चाल 10 किमी/घं बढ़ा दे तो 300 किमी की यात्रा 1 घंटा कम समय में पूरी करती है। ट्रेन की मूल चाल क्या है?","o":["40 किमी/घं","60 किमी/घं","50 किमी/घं","45 किमी/घं"],"a":2,"e":"<b>हल:</b><br>चरण 1: माना मूल चाल = v ⇒ 300/v − 300/(v + 10) = 1<br>चरण 2: 300 × 10/[v(v + 10)] = 1 ⇒ v(v + 10) = 3000<br>चरण 3: v² + 10v − 3000 = 0 ⇒ (v + 60)(v − 50) = 0 ⇒ v = 50<br>अतः उत्तर = <b>50 किमी/घं</b><br><b>शॉर्टकट:</b> विकल्प जाँचें — 300/50 = 6, 300/60 = 5, अंतर 1 घंटा ✓"},
    {"q":"एक व्यक्ति कुछ दूरी 5 किमी/घं से पैदल और शेष 10 किमी/घं से दौड़कर, कुल 20 किमी 3 घंटे में तय करता है। उसने कितनी दूरी पैदल तय की?","o":["8 किमी","12 किमी","15 किमी","10 किमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: माना पैदल दूरी = x ⇒ दौड़कर = 20 − x<br>चरण 2: x/5 + (20 − x)/10 = 3<br>चरण 3: 10 से गुणा ⇒ 2x + 20 − x = 30 ⇒ x = 10<br>अतः उत्तर = <b>10 किमी</b><br><b>जाँच:</b> 10/5 + 10/10 = 2 + 1 = 3 घंटे ✓"},
    {"q":"36 किमी/घं की चाल से 1 सेकंड में कितनी दूरी तय होगी?","o":["10 मी","36 मी","3.6 मी","1 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: 36 किमी/घं × 5/18 = 10 मी/से<br>चरण 2: 1 सेकंड में दूरी = 10 मी<br>अतः उत्तर = <b>10 मी</b>"},
    {"q":"45 किमी/घं की चाल से चलती ट्रेन 360 मी लंबे प्लेटफ़ॉर्म को 40 सेकंड में पार करती है। ट्रेन की लंबाई कितनी है?","o":["120 मी","140 मी","160 मी","180 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: चाल = 45 × 5/18 = 12.5 मी/से<br>चरण 2: 40 सेकंड में दूरी = 12.5 × 40 = 500 मी = ट्रेन + प्लेटफ़ॉर्म<br>चरण 3: ट्रेन = 500 − 360 = 140 मी<br>अतः उत्तर = <b>140 मी</b>"},
    {"q":"120 मी और 80 मी लंबी दो ट्रेनें विपरीत दिशाओं में 10 सेकंड में और एक ही दिशा में 40 सेकंड में एक-दूसरे को पार करती हैं। तेज़ ट्रेन की चाल क्या है?","o":["54 किमी/घं","36 किमी/घं","45 किमी/घं","40 किमी/घं"],"a":2,"e":"<b>हल:</b><br>चरण 1: कुल लंबाई = 120 + 80 = 200 मी<br>चरण 2: विपरीत दिशा: u + v = 200/10 = 20 मी/से<br>चरण 3: एक ही दिशा: u − v = 200/40 = 5 मी/से<br>चरण 4: जोड़ें ⇒ 2u = 25 ⇒ u = 12.5 मी/से = 12.5 × 18/5 = 45 किमी/घं<br>अतः उत्तर = <b>45 किमी/घं</b><br><b>ध्यान दें:</b> धीमी ट्रेन v = 7.5 मी/से = 27 किमी/घं।"},
    {"q":"A, X से Y तक 4 घंटे में और B, Y से X तक 6 घंटे में पहुँचता है। दोनों एक साथ चलें तो कितने समय बाद मिलेंगे?","o":["2 घंटे","3 घंटे","2 घंटे 30 मिनट","2 घंटे 24 मिनट"],"a":3,"e":"<b>हल:</b><br>चरण 1: माना दूरी = 12 (4 और 6 का LCM) ⇒ A की चाल = 3, B की चाल = 2<br>चरण 2: मिलने का समय = 12/(3 + 2) = 2.4 घंटे<br>चरण 3: 0.4 घंटा = 0.4 × 60 = 24 मिनट ⇒ 2 घंटे 24 मिनट<br>अतः उत्तर = <b>2 घंटे 24 मिनट</b><br><b>शॉर्टकट:</b> t = (4 × 6)/(4 + 6) = 2.4 घंटे<br><b>ध्यान दें:</b> 2.4 घंटे को 2 घंटे 40 मिनट न पढ़ें।"},
    {"q":"यदि कोई व्यक्ति 30 किमी/घं के स्थान पर 40 किमी/घं से चलता, तो उसी समय में 20 किमी अधिक दूरी तय करता। वास्तविक दूरी कितनी है?","o":["60 किमी","80 किमी","40 किमी","50 किमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: समान समय t में अतिरिक्त दूरी = (40 − 30) × t = 10t<br>चरण 2: 10t = 20 ⇒ t = 2 घंटे<br>चरण 3: वास्तविक दूरी = 30 × 2 = 60 किमी<br>अतः उत्तर = <b>60 किमी</b><br><b>ध्यान दें:</b> 80 किमी 40 किमी/घं वाली (काल्पनिक) दूरी है।"},
    {"q":"एक व्यक्ति 40 किमी/घं से किसी स्थान पर जाता है। उसे किस चाल से लौटना चाहिए कि पूरी यात्रा की औसत चाल 48 किमी/घं हो?","o":["56 किमी/घं","60 किमी/घं","64 किमी/घं","52 किमी/घं"],"a":1,"e":"<b>हल:</b><br>चरण 1: समान दूरी ⇒ औसत चाल = 2xy/(x + y)<br>चरण 2: 2 × 40 × y/(40 + y) = 48 ⇒ 80y = 48(40 + y) = 1920 + 48y<br>चरण 3: 32y = 1920 ⇒ y = 60<br>अतः उत्तर = <b>60 किमी/घं</b><br><b>ध्यान दें:</b> 56 (साधारण औसत से 2 × 48 − 40) गलत है।"},
    {"q":"A और B के बीच 450 किमी दूरी है। दो ट्रेनें एक साथ A से 60 किमी/घं और B से 90 किमी/घं से एक-दूसरे की ओर चलती हैं। मिलन स्थल A से कितनी दूर होगा?","o":["270 किमी","150 किमी","180 किमी","225 किमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: सापेक्ष चाल = 60 + 90 = 150 किमी/घं<br>चरण 2: मिलने का समय = 450/150 = 3 घंटे<br>चरण 3: A से दूरी = 60 × 3 = 180 किमी<br>अतः उत्तर = <b>180 किमी</b><br><b>शॉर्टकट:</b> दूरी चाल के अनुपात 60 : 90 = 2 : 3 में बँटती है ⇒ 450 × 2/5 = 180<br><b>ध्यान दें:</b> 270 किमी B से दूरी है।"},
    {"q":"धारा की चाल 5 किमी/घं है। एक नाव धारा के प्रतिकूल 2 घंटे में 20 किमी जाती है। वही नाव धारा के अनुकूल 2 घंटे में कितनी दूरी तय करेगी?","o":["30 किमी","50 किमी","20 किमी","40 किमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: प्रतिकूल चाल U = 20/2 = 10 किमी/घं<br>चरण 2: नाव की चाल = U + धारा = 10 + 5 = 15 किमी/घं<br>चरण 3: अनुकूल चाल = 15 + 5 = 20 किमी/घं<br>चरण 4: 2 घंटे में दूरी = 20 × 2 = 40 किमी<br>अतः उत्तर = <b>40 किमी</b>"},
    {"q":"एक ट्रेन प्लेटफ़ॉर्म पर खड़े व्यक्ति को 8 सेकंड में और 264 मी लंबे प्लेटफ़ॉर्म को 20 सेकंड में पार करती है। ट्रेन की लंबाई कितनी है?","o":["176 मी","160 मी","198 मी","220 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: व्यक्ति: L = v × 8; प्लेटफ़ॉर्म: L + 264 = v × 20<br>चरण 2: घटाएँ ⇒ 264 = 12v ⇒ v = 22 मी/से<br>चरण 3: L = 22 × 8 = 176 मी<br>अतः उत्तर = <b>176 मी</b>"},
    {"q":"108 किमी/घं = ? मी/से","o":["32","30","36","27"],"a":1,"e":"<b>हल:</b><br>चरण 1: किमी/घं से मी/से ⇒ × 5/18<br>चरण 2: 108 × 5/18 = 6 × 5 = 30<br>अतः उत्तर = <b>30 मी/से</b>"},
    {"q":"एक व्यक्ति किसी स्थान तक 60 किमी/घं से जाता है और 40 किमी/घं से लौटता है। आने-जाने में कुल 5 घंटे लगते हैं। एक ओर की दूरी कितनी है?","o":["100 किमी","150 किमी","120 किमी","140 किमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: माना एक ओर की दूरी = d ⇒ d/60 + d/40 = 5<br>चरण 2: LCM 120 ⇒ (2d + 3d)/120 = 5 ⇒ 5d = 600<br>चरण 3: d = 120<br>अतः उत्तर = <b>120 किमी</b><br><b>शॉर्टकट:</b> औसत चाल = 2 × 60 × 40/100 = 48; कुल दूरी = 48 × 5 = 240 ⇒ एक ओर 120"},
    {"q":"एक ट्रेन अपनी ही दिशा में 2 किमी/घं और 4 किमी/घं से चल रहे दो व्यक्तियों को क्रमशः 9 सेकंड और 10 सेकंड में पार करती है। ट्रेन की लंबाई कितनी है?","o":["50 मी","45 मी","60 मी","55 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: माना ट्रेन की चाल = v किमी/घं; ट्रेन की लंबाई दोनों स्थितियों में समान<br>चरण 2: (v − 2) × 9 = (v − 4) × 10 (इकाई का गुणक 5/18 दोनों ओर कट जाता है)<br>चरण 3: 9v − 18 = 10v − 40 ⇒ v = 22 किमी/घं<br>चरण 4: लंबाई = (22 − 2) × 5/18 × 9 = 20 × 5/18 × 9 = 50 मी<br>अतः उत्तर = <b>50 मी</b><br><b>जाँच:</b> (22 − 4) × 5/18 × 10 = 5 × 10 = 50 ✓"},
    {"q":"54 किमी/घं से चल रही ट्रेन में बैठा एक व्यक्ति देखता है कि विपरीत दिशा से 72 किमी/घं से आ रही दूसरी ट्रेन उसे 8 सेकंड में पार कर जाती है। दूसरी ट्रेन की लंबाई कितनी है?","o":["40 मी","280 मी","144 मी","160 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: विपरीत दिशा ⇒ सापेक्ष चाल = 54 + 72 = 126 किमी/घं = 126 × 5/18 = 35 मी/से<br>चरण 2: व्यक्ति बिंदु-वस्तु है ⇒ तय दूरी = केवल दूसरी ट्रेन की लंबाई<br>चरण 3: लंबाई = 35 × 8 = 280 मी<br>अतः उत्तर = <b>280 मी</b><br><b>ध्यान दें:</b> 40 मी (सापेक्ष चाल 18 किमी/घं) एक ही दिशा मानने से आता है; अपनी ट्रेन की लंबाई नहीं जुड़ती।"},
    {"q":"दो ट्रेनें P और Q से एक साथ एक-दूसरे की ओर चलीं। मिलने के बाद उन्हें अपने-अपने गंतव्य तक पहुँचने में क्रमशः 4 घंटे और 9 घंटे लगे। चलने के कितने समय बाद वे मिली थीं?","o":["6.5 घंटे","5 घंटे","6 घंटे","13 घंटे"],"a":2,"e":"<b>हल:</b><br>चरण 1: माना मिलने में t घंटे लगे; चालें v₁ (P से), v₂ (Q से)<br>चरण 2: मिलन बिंदु से Q तक दूरी: v₂t = 4v₁ (P वाली ट्रेन इसे 4 घंटे में तय करती है)<br>चरण 3: मिलन बिंदु से P तक: v₁t = 9v₂<br>चरण 4: दोनों को गुणा ⇒ v₁v₂t² = 36v₁v₂ ⇒ t² = 36 ⇒ t = 6<br>अतः उत्तर = <b>6 घंटे</b><br><b>शॉर्टकट:</b> t = √(a × b) = √(4 × 9) = 6<br><b>ध्यान दें:</b> 6.5 (साधारण औसत) गलत है।"},
    {"q":"एक नाव 24 किमी धारा के प्रतिकूल और 36 किमी धारा के अनुकूल 6 घंटे में जाती है। वही नाव 36 किमी प्रतिकूल और 24 किमी अनुकूल 6.5 घंटे में जाती है। स्थिर जल में नाव की चाल क्या है?","o":["12 किमी/घं","8 किमी/घं","9 किमी/घं","10 किमी/घं"],"a":3,"e":"<b>हल:</b><br>चरण 1: माना 1/U = x, 1/D = y (U = प्रतिकूल, D = अनुकूल चाल)<br>चरण 2: 24x + 36y = 6 … (i); 36x + 24y = 6.5 … (ii)<br>चरण 3: (i) + (ii) ⇒ 60(x + y) = 12.5; (ii) − (i) ⇒ 12(x − y) = 0.5 ⇒ x − y = 1/24<br>चरण 4: x + y = 12.5/60 = 5/24 ⇒ 2x = 6/24 ⇒ x = 1/8, y = 1/12 ⇒ U = 8, D = 12<br>चरण 5: नाव = (8 + 12)/2 = 10 किमी/घं (धारा = 2)<br>अतः उत्तर = <b>10 किमी/घं</b><br><b>जाँच:</b> 24/8 + 36/12 = 3 + 3 = 6 ✓; 36/8 + 24/12 = 4.5 + 2 = 6.5 ✓<br><b>ध्यान दें:</b> 12 किमी/घं अनुकूल चाल है।"},
    {"q":"A, B से 1 2/3 गुना तेज़ दौड़ता है। A, B को 80 मी की बढ़त देता है। दौड़ कितने मीटर की हो कि दोनों एक साथ पहुँचें?","o":["200 मी","160 मी","240 मी","120 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: A की चाल = 1 2/3 = 5/3 × B ⇒ A : B = 5 : 3<br>चरण 2: समान समय में दूरी ∝ चाल ⇒ A 5 भाग, B 3 भाग चलता है<br>चरण 3: बढ़त = 5 − 3 = 2 भाग = 80 मी ⇒ 1 भाग = 40 मी<br>चरण 4: दौड़ (A की दूरी) = 5 × 40 = 200 मी<br>अतः उत्तर = <b>200 मी</b><br><b>ध्यान दें:</b> 120 मी B द्वारा दौड़ी गई दूरी है।"},
    {"q":"एक सिपाही 200 मी दूर एक चोर को देखता है और उसका पीछा करता है। चोर 10 किमी/घं और सिपाही 12 किमी/घं से दौड़ता है। पकड़े जाने तक चोर कितनी दूरी दौड़ चुका होगा?","o":["1.2 किमी","1 किमी","200 मी","800 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक ही दिशा ⇒ सापेक्ष चाल = 12 − 10 = 2 किमी/घं<br>चरण 2: पकड़ने का समय = 0.2 किमी/2 = 0.1 घंटा<br>चरण 3: इस समय में चोर की दूरी = 10 × 0.1 = 1 किमी<br>अतः उत्तर = <b>1 किमी</b><br><b>ध्यान दें:</b> 1.2 किमी सिपाही की दूरी है; 200 मी केवल आरंभिक अंतर।"},
    {"q":"एक कार कुल दूरी का 25% भाग 20 किमी/घं से और शेष 75% भाग 60 किमी/घं से तय करती है। पूरी यात्रा में औसत चाल क्या है?","o":["50 किमी/घं","45 किमी/घं","40 किमी/घं","30 किमी/घं"],"a":2,"e":"<b>हल:</b><br>चरण 1: माना कुल दूरी = 100 किमी ⇒ 25 किमी 20 किमी/घं से, 75 किमी 60 किमी/घं से<br>चरण 2: समय = 25/20 + 75/60 = 1.25 + 1.25 = 2.5 घंटे<br>चरण 3: औसत चाल = 100/2.5 = 40<br>अतः उत्तर = <b>40 किमी/घं</b><br><b>ध्यान दें:</b> 50 (भारित औसत 0.25 × 20 + 0.75 × 60) गलत है — भार समय से लगता है, दूरी से नहीं।"},
    {"q":"1.4 मी व्यास वाले पहियों की एक गाड़ी 66 किमी/घं से चल रही है। प्रत्येक पहिया प्रति मिनट कितने चक्कर लगाएगा? (π = 22/7)","o":["300","150","200","250"],"a":3,"e":"<b>हल:</b><br>चरण 1: परिधि = πd = 22/7 × 1.4 = 4.4 मी<br>चरण 2: चाल = 66 किमी/घं = 66000 मी प्रति 60 मिनट ⇒ प्रति मिनट 1100 मी<br>चरण 3: चक्कर प्रति मिनट = 1100/4.4 = 250<br>अतः उत्तर = <b>250</b>"},
    {"q":"120 मी लंबाई की दो ट्रेनें एक खंभे को क्रमशः 10 सेकंड और 15 सेकंड में पार करती हैं। विपरीत दिशाओं में चलते हुए वे एक-दूसरे को कितने समय में पार करेंगी?","o":["12.5 सेकंड","12 सेकंड","25 सेकंड","10 सेकंड"],"a":1,"e":"<b>हल:</b><br>चरण 1: चालें — 120/10 = 12 मी/से और 120/15 = 8 मी/से<br>चरण 2: विपरीत दिशा ⇒ सापेक्ष चाल = 12 + 8 = 20 मी/से<br>चरण 3: दूरी = 120 + 120 = 240 मी ⇒ समय = 240/20 = 12 सेकंड<br>अतः उत्तर = <b>12 सेकंड</b><br><b>ध्यान दें:</b> 12.5 सेकंड (10 और 15 का औसत) गलत है।"},
    {"q":"एक ही स्थान से 13 मिनट के अंतराल पर दो तोपें दागी गईं। उस स्थान की ओर आ रही ट्रेन में बैठे व्यक्ति ने दूसरी आवाज़ पहली के 12 मिनट 30 सेकंड बाद सुनी। ध्वनि की चाल 330 मी/से हो, तो ट्रेन की चाल क्या है?","o":["47.52 किमी/घं","45 किमी/घं","52.47 किमी/घं","13.2 किमी/घं"],"a":0,"e":"<b>हल:</b><br>चरण 1: यदि ट्रेन रुकी होती, तो दूसरी आवाज़ 13 मिनट बाद सुनाई देती; अंतर = 13 − 12.5 = 0.5 मिनट = 30 सेकंड<br>चरण 2: यह 30 सेकंड इसलिए बचे कि ट्रेन 12.5 मिनट में उतनी दूरी आगे बढ़ गई जितनी ध्वनि 30 सेकंड में चलती है = 330 × 30 = 9900 मी<br>चरण 3: ट्रेन की चाल = 9900/(12.5 × 60) = 9900/750 = 13.2 मी/से<br>चरण 4: 13.2 × 18/5 = 47.52 किमी/घं<br>अतः उत्तर = <b>47.52 किमी/घं</b><br><b>ध्यान दें:</b> 13.2 मी/से में है, किमी/घं में नहीं।"},
    {"q":"स्थिर जल में नाव की चाल 5 किमी/घं है। किसी स्थान तक 2.4 किमी जाकर लौटने में 1 घंटा लगता है। धारा की चाल क्या है?","o":["1.5 किमी/घं","2 किमी/घं","1 किमी/घं","0.5 किमी/घं"],"a":2,"e":"<b>हल:</b><br>चरण 1: माना धारा = s ⇒ 2.4/(5 + s) + 2.4/(5 − s) = 1<br>चरण 2: 2.4 × [(5 − s) + (5 + s)]/(25 − s²) = 1 ⇒ 24/(25 − s²) = 1<br>चरण 3: 25 − s² = 24 ⇒ s² = 1 ⇒ s = 1<br>अतः उत्तर = <b>1 किमी/घं</b><br><b>जाँच:</b> 2.4/6 + 2.4/4 = 0.4 + 0.6 = 1 घंटा ✓"},
    {"q":"100 मी की दौड़ में A, B को 20 मी या 4 सेकंड से हराता है। A दौड़ कितने समय में पूरी करता है?","o":["20 सेकंड","15 सेकंड","24 सेकंड","16 सेकंड"],"a":3,"e":"<b>हल:</b><br>चरण 1: A के समाप्त होने पर B 20 मी पीछे है और उसे 4 सेकंड और लगते हैं<br>चरण 2: B की चाल = 20/4 = 5 मी/से ⇒ B का 100 मी का समय = 100/5 = 20 सेकंड<br>चरण 3: A का समय = 20 − 4 = 16 सेकंड<br>अतः उत्तर = <b>16 सेकंड</b><br><b>ध्यान दें:</b> 20 सेकंड B का समय है।"},
    {"q":"दो कारें एक ही दिशा में चलें तो उनकी सापेक्ष चाल 10 किमी/घं और विपरीत दिशा में चलें तो 70 किमी/घं होती है। तेज़ कार की चाल क्या है?","o":["40 किमी/घं","35 किमी/घं","30 किमी/घं","70 किमी/घं"],"a":0,"e":"<b>हल:</b><br>चरण 1: एक ही दिशा ⇒ a − b = 10; विपरीत ⇒ a + b = 70<br>चरण 2: जोड़ें ⇒ 2a = 80 ⇒ a = 40; b = 30<br>अतः उत्तर = <b>40 किमी/घं</b><br><b>ध्यान दें:</b> 30 धीमी कार की चाल है।"},
    {"q":"एक ट्रेन और एक कार की चालों का अनुपात 16 : 15 है। एक बस की चाल कार की चाल की 3/4 है। बस 8 घंटे में 360 किमी जाती है। ट्रेन की चाल क्या है?","o":["60 किमी/घं","64 किमी/घं","80 किमी/घं","48 किमी/घं"],"a":1,"e":"<b>हल:</b><br>चरण 1: बस की चाल = 360/8 = 45 किमी/घं<br>चरण 2: बस = 3/4 × कार ⇒ कार = 45 × 4/3 = 60 किमी/घं<br>चरण 3: ट्रेन : कार = 16 : 15 ⇒ ट्रेन = 60 × 16/15 = 64 किमी/घं<br>अतः उत्तर = <b>64 किमी/घं</b><br><b>ध्यान दें:</b> 60 कार की चाल है।"},
    {"q":"150 मी लंबी एक ट्रेन विपरीत दिशा से 6 किमी/घं से दौड़ते व्यक्ति को 6 सेकंड में पार करती है। ट्रेन की चाल क्या है?","o":["90 किमी/घं","96 किमी/घं","84 किमी/घं","78 किमी/घं"],"a":2,"e":"<b>हल:</b><br>चरण 1: सापेक्ष चाल = 150/6 = 25 मी/से = 25 × 18/5 = 90 किमी/घं<br>चरण 2: विपरीत दिशा ⇒ सापेक्ष चाल = v + 6 = 90<br>चरण 3: v = 84 किमी/घं<br>अतः उत्तर = <b>84 किमी/घं</b><br><b>ध्यान दें:</b> 90 सापेक्ष चाल है; 96 (90 + 6) एक ही दिशा का उत्तर है।"},
    {"q":"बिजली चमकने के 5 सेकंड बाद बादल की गरज सुनाई दी। ध्वनि की चाल 330 मी/से हो, तो बादल कितनी दूर है? (प्रकाश का समय नगण्य)","o":["16.5 किमी","0.165 किमी","1.5 किमी","1.65 किमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: प्रकाश लगभग तुरंत पहुँचता है ⇒ 5 सेकंड ध्वनि का यात्रा-समय है<br>चरण 2: दूरी = 330 × 5 = 1650 मी<br>चरण 3: 1650 मी = 1.65 किमी<br>अतः उत्तर = <b>1.65 किमी</b><br><b>ध्यान दें:</b> मी से किमी में बदलते समय 1000 से भाग दें — 16.5 और 0.165 दशमलव की गलती हैं।"},
    {"q":"एक ट्रेन 4 घंटे 60 किमी/घं से चली, फिर 1 घंटा रुकी, फिर 2 घंटे 90 किमी/घं से चली। ठहराव सहित पूरी यात्रा में औसत चाल क्या है?","o":["70 किमी/घं","60 किमी/घं","75 किमी/घं","50 किमी/घं"],"a":1,"e":"<b>हल:</b><br>चरण 1: कुल दूरी = 60 × 4 + 90 × 2 = 240 + 180 = 420 किमी<br>चरण 2: कुल समय (ठहराव सहित) = 4 + 1 + 2 = 7 घंटे<br>चरण 3: औसत चाल = 420/7 = 60<br>अतः उत्तर = <b>60 किमी/घं</b><br><b>ध्यान दें:</b> ठहराव छोड़ने पर 420/6 = 70 आता है — पर प्रश्न ठहराव सहित पूछ रहा है।"},
    {"q":"1 किमी लंबे वृत्ताकार पथ पर दो व्यक्ति विपरीत दिशाओं में चलें तो हर 2 मिनट पर और एक ही दिशा में चलें तो हर 10 मिनट पर मिलते हैं। तेज़ व्यक्ति की चाल क्या है?","o":["18 किमी/घं","12 किमी/घं","15 किमी/घं","20 किमी/घं"],"a":0,"e":"<b>हल:</b><br>चरण 1: विपरीत दिशा ⇒ a + b = 1 किमी/2 मिनट = 30 किमी/घं<br>चरण 2: एक ही दिशा ⇒ a − b = 1 किमी/10 मिनट = 6 किमी/घं<br>चरण 3: a = (30 + 6)/2 = 18; b = 12<br>अतः उत्तर = <b>18 किमी/घं</b><br><b>ध्यान दें:</b> 12 किमी/घं धीमे व्यक्ति की चाल है।"},
    {"q":"एक ट्रेन b घंटे में a किमी दूरी तय करती है। उसी चाल से c किमी दूरी तय करने में कितना समय लगेगा?","o":["ab/c घंटे","ac/b घंटे","bc/a घंटे","a/bc घंटे"],"a":2,"e":"<b>हल:</b><br>चरण 1: चाल = दूरी/समय = a/b किमी/घं<br>चरण 2: c किमी का समय = c ÷ (a/b) = c × b/a = bc/a<br>अतः उत्तर = <b>bc/a घंटे</b><br><b>जाँच:</b> a = 60, b = 2, c = 90 ⇒ चाल 30, समय 3 = 2 × 90/60 ✓"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. यदि दो बराबर दूरियाँ x और y चालों से तय की जाएँ, तो औसत चाल 2xy/(x + y) होती है।<br>2. यदि दो बराबर समय-अंतराल x और y चालों से चला जाए, तब भी औसत चाल 2xy/(x + y) ही होती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>चरण 1 (कथन 1): समान दूरी d — कुल समय d/x + d/y ⇒ औसत = 2d ÷ (d/x + d/y) = 2xy/(x + y) ⇒ <b>सही</b><br>चरण 2 (कथन 2): समान समय t — कुल दूरी xt + yt ⇒ औसत = (x + y)t/2t = (x + y)/2 (साधारण औसत) ⇒ <b>गलत</b><br>अतः उत्तर = <b>केवल 1</b>"},
    {"q":"अभिकथन (A): कोई ट्रेन किसी खंभे को पार करते समय केवल अपनी लंबाई के बराबर दूरी तय करती है।<br>कारण (R): खंभे की लंबाई (मोटाई) ट्रेन की तुलना में नगण्य मानी जाती है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"<b>हल:</b><br>चरण 1 (A): खंभे को पार करना = ट्रेन का अगला सिरा खंभे पर से पिछला सिरा खंभे से आगे निकलने तक ⇒ दूरी = ट्रेन की लंबाई ⇒ <b>सही</b><br>चरण 2 (R): खंभे की मोटाई ट्रेन की लंबाई की तुलना में नगण्य है ⇒ <b>सही</b><br>चरण 3: R ही कारण है कि खंभे की लंबाई नहीं जोड़ी जाती ⇒ R, A की सही व्याख्या है<br>अतः उत्तर = <b>A और R दोनों सही हैं तथा R, A की सही व्याख्या है</b><br><b>ध्यान दें:</b> प्लेटफ़ॉर्म/पुल की लंबाई नगण्य नहीं होती, इसलिए वह जुड़ती है।"},
    {"q":"सूची-I को सूची-II से सुमेलित कीजिए —<br>(A) 36 किमी/घं (B) 54 किमी/घं (C) 90 किमी/घं (D) 126 किमी/घं<br>1. 25 मी/से 2. 35 मी/से 3. 10 मी/से 4. 15 मी/से","o":["A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"a":3,"e":"<b>हल:</b><br>चरण 1: किमी/घं × 5/18 = मी/से<br>चरण 2: (A) 36 × 5/18 = 10 ⇒ A-3; (B) 54 × 5/18 = 15 ⇒ B-4<br>चरण 3: (C) 90 × 5/18 = 25 ⇒ C-1; (D) 126 × 5/18 = 35 ⇒ D-2<br>अतः उत्तर = <b>A-3, B-4, C-1, D-2</b>"},
    {"q":"एक कस्बे से हर 10 मिनट पर 20 किमी/घं की चाल वाली एक बस निकलती है। कस्बे की ओर पैदल आ रहे एक व्यक्ति को हर 8 मिनट पर एक बस मिलती है। व्यक्ति की चाल क्या है?","o":["4 किमी/घं","6 किमी/घं","4.5 किमी/घं","5 किमी/घं"],"a":3,"e":"<b>हल:</b><br>चरण 1: लगातार दो बसों के बीच दूरी = 20 × 10/60 = 10/3 किमी<br>चरण 2: व्यक्ति बसों की ओर आ रहा है ⇒ सापेक्ष चाल = 20 + v<br>चरण 3: यह दूरी 8 मिनट में तय होती है ⇒ (20 + v) × 8/60 = 10/3<br>चरण 4: 20 + v = 10/3 × 60/8 = 25 ⇒ v = 5<br>अतः उत्तर = <b>5 किमी/घं</b>"},
    {"q":"दो कारें एक ही स्थान से एक ही दिशा में 40 किमी/घं और 50 किमी/घं से एक साथ चलती हैं। कितने समय बाद उनके बीच 20 किमी की दूरी होगी?","o":["2 घंटे","4 घंटे","1 घंटा","20 मिनट"],"a":0,"e":"<b>हल:</b><br>चरण 1: एक ही दिशा ⇒ सापेक्ष चाल = 50 − 40 = 10 किमी/घं<br>चरण 2: समय = 20/10 = 2 घंटे<br>अतः उत्तर = <b>2 घंटे</b>"},
    {"q":"एक व्यक्ति किसी स्थान तक पैदल जाकर सवारी से लौटने में 6 घंटे 15 मिनट लगाता है। दोनों ओर पैदल जाने में उसे 7 घंटे 45 मिनट लगते हैं। दोनों ओर सवारी से जाने में कितना समय लगेगा?","o":["4 घंटे 45 मिनट","3 घंटे 45 मिनट","5 घंटे 15 मिनट","4 घंटे 15 मिनट"],"a":0,"e":"<b>हल:</b><br>चरण 1: माना एक ओर पैदल = W, सवारी = R<br>चरण 2: W + R = 6 घं 15 मि; 2W = 7 घं 45 मि<br>चरण 3: 2R = 2(W + R) − 2W = 12 घं 30 मि − 7 घं 45 मि = 4 घं 45 मि<br>अतः उत्तर = <b>4 घंटे 45 मिनट</b><br><b>ध्यान दें:</b> 1 घं 30 मि (7:45 − 6:15) केवल W − R है।"},
    {"q":"4.5 किमी/घं की चाल से 1.5 किमी चलने में कितना समय लगेगा?","o":["30 मिनट","20 मिनट","15 मिनट","25 मिनट"],"a":1,"e":"<b>हल:</b><br>चरण 1: समय = दूरी/चाल = 1.5/4.5 = 1/3 घंटा<br>चरण 2: 1/3 × 60 = 20 मिनट<br>अतः उत्तर = <b>20 मिनट</b>"},
    {"q":"एक ट्रेन सुबह 9:15 बजे चलती है और 420 किमी की दूरी 70 किमी/घं की औसत चाल से तय करती है। वह कितने बजे पहुँचेगी?","o":["2:15 PM","4:15 PM","3:45 PM","3:15 PM"],"a":3,"e":"<b>हल:</b><br>चरण 1: यात्रा का समय = 420/70 = 6 घंटे<br>चरण 2: 9:15 AM + 6 घंटे = 15:15 = 3:15 PM<br>अतः उत्तर = <b>3:15 PM</b>"},
    {"q":"वर्षा के कारण एक बस की चाल 50 किमी/घं से घटकर 40 किमी/घं हो गई। 200 किमी की यात्रा में कितना अधिक समय लगेगा?","o":["1 घंटा","50 मिनट","40 मिनट","1 घंटा 15 मिनट"],"a":0,"e":"<b>हल:</b><br>चरण 1: 50 किमी/घं से समय = 200/50 = 4 घंटे<br>चरण 2: 40 किमी/घं से समय = 200/40 = 5 घंटे<br>चरण 3: अतिरिक्त समय = 5 − 4 = 1 घंटा<br>अतः उत्तर = <b>1 घंटा</b>"},
    {"q":"A एक दूरी 40 मिनट में और B वही दूरी 1 घंटे में तय करता है। A और B की चालों का अनुपात क्या है?","o":["2 : 3","3 : 2","4 : 3","3 : 4"],"a":1,"e":"<b>हल:</b><br>चरण 1: समय — A = 40 मिनट, B = 60 मिनट (एक ही इकाई में)<br>चरण 2: दूरी समान ⇒ चाल ∝ 1/समय ⇒ A : B = 60 : 40 = 3 : 2<br>अतः उत्तर = <b>3 : 2</b><br><b>ध्यान दें:</b> 2 : 3 समयों का अनुपात है।"},
    {"q":"एक बस पहले घंटे में 30 किमी/घं से चलती है और हर अगले घंटे अपनी चाल 5 किमी/घं बढ़ा देती है। 6 घंटे में वह कुल कितनी दूरी तय करेगी?","o":["330 किमी","180 किमी","225 किमी","255 किमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: हर घंटे की दूरी — 30, 35, 40, 45, 50, 55 किमी (समांतर श्रेणी, अंतर 5)<br>चरण 2: योग = n/2 × (पहला + अंतिम) = 6/2 × (30 + 55) = 3 × 85 = 255<br>अतः उत्तर = <b>255 किमी</b><br><b>ध्यान दें:</b> 180 (30 × 6) चाल-वृद्धि की उपेक्षा से आता है।"},
    {"q":"दो साइकिल सवार एक ही स्थान से विपरीत दिशाओं में 12 किमी/घं और 15 किमी/घं से एक साथ चलते हैं। 2.5 घंटे बाद उनके बीच कितनी दूरी होगी?","o":["7.5 किमी","54 किमी","67.5 किमी","60 किमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: विपरीत दिशा ⇒ दूरी बढ़ने की दर = 12 + 15 = 27 किमी/घं<br>चरण 2: 2.5 घंटे में दूरी = 27 × 2.5 = 67.5 किमी<br>अतः उत्तर = <b>67.5 किमी</b><br><b>ध्यान दें:</b> 7.5 किमी तब आता है जब दोनों एक ही दिशा में चलें।"},
    {"q":"स्थिर जल में नाव की चाल 15 किमी/घं और धारा की चाल 3 किमी/घं है। धारा के अनुकूल 12 मिनट में नाव कितनी दूरी तय करेगी?","o":["3 किमी","2.4 किमी","3.6 किमी","4.8 किमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: अनुकूल चाल = 15 + 3 = 18 किमी/घं<br>चरण 2: समय = 12 मिनट = 12/60 = 1/5 घंटा<br>चरण 3: दूरी = 18 × 1/5 = 3.6 किमी<br>अतः उत्तर = <b>3.6 किमी</b><br><b>ध्यान दें:</b> 2.4 किमी प्रतिकूल चाल (12) से आता है।"},
    {"q":"तीन वाहनों की चालों का अनुपात 2 : 3 : 4 है। समान दूरी तय करने में लगे समयों का अनुपात क्या होगा?","o":["4 : 3 : 2","6 : 4 : 3","2 : 3 : 4","3 : 4 : 6"],"a":1,"e":"<b>हल:</b><br>चरण 1: दूरी समान ⇒ समय ∝ 1/चाल ⇒ 1/2 : 1/3 : 1/4<br>चरण 2: LCM 12 से गुणा ⇒ 6 : 4 : 3<br>अतः उत्तर = <b>6 : 4 : 3</b><br><b>ध्यान दें:</b> केवल क्रम उलटकर 4 : 3 : 2 लिखना आम भूल है (तीन पदों में यह सही नहीं होता)।"},
    {"q":"एक चोर दोपहर 2:30 बजे कार चुराकर 60 किमी/घं से भागता है। चोरी का पता 3:00 बजे चलता है और मालिक 75 किमी/घं से पीछा करता है। मालिक चोर को कितने बजे पकड़ेगा?","o":["5:00 PM","4:30 PM","5:30 PM","4:00 PM"],"a":0,"e":"<b>हल:</b><br>चरण 1: 2:30 से 3:00 (1/2 घंटा) में चोर = 60 × 1/2 = 30 किमी आगे<br>चरण 2: सापेक्ष चाल = 75 − 60 = 15 किमी/घं<br>चरण 3: पकड़ने का समय = 30/15 = 2 घंटे ⇒ 3:00 + 2 = 5:00 PM<br>अतः उत्तर = <b>5:00 PM</b><br><b>ध्यान दें:</b> 2 घंटे 3:00 से गिनें, 2:30 से नहीं (4:30 गलत)।"},
    {"q":"एक ट्रेन अपनी दिशा में 3 किमी/घं से चल रहे व्यक्ति को 10 सेकंड में और विपरीत दिशा में 3 किमी/घं से चल रहे दूसरे व्यक्ति को 9 सेकंड में पार करती है। ट्रेन की लंबाई कितनी है?","o":["135 मी","165 मी","120 मी","150 मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: माना ट्रेन की चाल v किमी/घं; लंबाई दोनों स्थितियों में समान<br>चरण 2: (v − 3) × 10 = (v + 3) × 9 (5/18 का गुणक दोनों ओर कटता है)<br>चरण 3: 10v − 30 = 9v + 27 ⇒ v = 57 किमी/घं<br>चरण 4: लंबाई = (57 − 3) × 5/18 × 10 = 54 × 5/18 × 10 = 15 × 10 = 150 मी<br>अतः उत्तर = <b>150 मी</b><br><b>जाँच:</b> (57 + 3) × 5/18 × 9 = 60 × 5/18 × 9 = 150 ✓"},
    {"q":"एक लड़का 20 किमी दूरी 2.5 घंटे में दौड़ता है। अपनी दोगुनी चाल से वह 32 किमी कितने समय में तय करेगा?","o":["4 घंटे","2 घंटे","2.5 घंटे","1.5 घंटे"],"a":1,"e":"<b>हल:</b><br>चरण 1: चाल = 20/2.5 = 8 किमी/घं<br>चरण 2: दोगुनी चाल = 16 किमी/घं<br>चरण 3: समय = 32/16 = 2 घंटे<br>अतः उत्तर = <b>2 घंटे</b><br><b>ध्यान दें:</b> 4 घंटे सामान्य चाल का समय है।"},
    {"q":"48 किमी/घं से चल रही एक ट्रेन विपरीत दिशा में 42 किमी/घं से आ रही अपने से आधी लंबाई वाली ट्रेन को 12 सेकंड में पार करती है। वही ट्रेन एक प्लेटफ़ॉर्म को 45 सेकंड में पार करती है। प्लेटफ़ॉर्म की लंबाई कितनी है?","o":["300 मी","600 मी","400 मी","200 मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: विपरीत दिशा ⇒ सापेक्ष चाल = 48 + 42 = 90 किमी/घं = 25 मी/से<br>चरण 2: 12 सेकंड में दूरी = 25 × 12 = 300 मी = L + L/2 = 3L/2 ⇒ L = 200 मी<br>चरण 3: ट्रेन की चाल = 48 × 5/18 = 40/3 मी/से; 45 सेकंड में = 40/3 × 45 = 600 मी<br>चरण 4: 600 = L + P ⇒ P = 600 − 200 = 400 मी<br>अतः उत्तर = <b>400 मी</b><br><b>ध्यान दें:</b> 600 मी में ट्रेन की लंबाई भी शामिल है।"}
  ]
});
